function characterList(kind){
  if(kind==='hero') return Object.values(CHARACTER_LIBRARY.heroes).map(clone);
  if(kind==='villain') return Object.values(CHARACTER_LIBRARY.villains).map(clone);
  return { heroes: characterList('hero'), villains: characterList('villain') };
}
function getChar(kind,id){ const bucket = kind==='hero' ? CHARACTER_LIBRARY.heroes : CHARACTER_LIBRARY.villains; return bucket[id] ? clone(bucket[id]) : null; }
function buildScenarioPieces(heroes){
  return heroes.slice(0,6).map((h,i)=>({id:`hero-${h.id}`,kind:'hero',baseId:h.id,name:h.n,short:h.n.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),color:['#ef4444','#facc15','#3b82f6','#22c55e','#a855f7','#06b6d4'][i%6],x:2+i*2,y:12,movement:h.movement||{run:5,climb:3,swim:3,jump:3}}));
}
function buildTemplate({id,name,subtitle,rank,players,finalVillain,accent,summary,source='uploaded-campaign',campaignPdf='',heroIds=[],villainIds=[],sessions=[]}){
  return { id,name,subtitle,rank,players,finalVillain,accent,summary,source,campaignPdf, heroes: heroIds.map(heroId=>getChar('hero',heroId)).filter(Boolean), villains: villainIds.map(villainId=>getChar('villain',villainId)).filter(Boolean), sessions };
}

