export function publicTemplate(template){
  return {
    id:template.id,name:template.name,subtitle:template.subtitle,rank:template.rank,players:template.players,finalVillain:template.finalVillain,accent:template.accent,summary:template.summary,source:template.source,campaignPdf:template.campaignPdf||'',
    heroes:rosterSummary(template.heroes,'hero'),
    villains:rosterSummary(template.villains,'villain'),
    sessions:template.sessions.map(s=>({id:s.id,title:s.title,text:s.text}))
  };
}
export function getTemplates(){ return templates.map(clone); }
export function getTemplate(id){ const found = templates.find(t=>t.id===id); return found ? clone(found) : null; }
export function getCharacterLibrary(kind='all'){ return characterList(kind); }
export function getCharacter(kind,id){ return getChar(kind,id); }
export function applyRoster(seed,{heroIds=[],villainIds=[]}={}){
  const next = clone(seed || blankSeed('Nova Campanha'));
  if(Array.isArray(heroIds)) next.heroes = [...new Set(heroIds)].map(id=>getChar('hero',id)).filter(Boolean);
  if(Array.isArray(villainIds)) next.villains = [...new Set(villainIds)].map(id=>getChar('villain',id)).filter(Boolean);
  next.playerNotes = Object.fromEntries((next.heroes||[]).map(hero=>[hero.id, next.playerNotes?.[hero.id] || '']));
  next.campaignContent = { ...(next.campaignContent||{}), players:(next.heroes||[]).length };
  const boss = (next.villains||[]).find(v=>v.tier==='CHEFE FINAL') || next.villains?.[0] || null;
  if(boss) next.campaignContent.finalVillain = boss.n;
  if(next.challenge) next.challenge.actor = next.heroes?.[0]?.id || '';
  if(next.scenario) next.scenario.pieces = buildScenarioPieces(next.heroes||[]);
  return next;
}
export function templateSeed(id){
  const t=getTemplate(id); if(!t) return null;
  return {
    heroes: clone(t.heroes),
    villains: clone(t.villains),
    campaign: Object.fromEntries(t.sessions.map(s=>[s.id,'todo'])),
    campaignContent:{ title:t.name, subtitle:t.subtitle, summary:t.summary, rank:t.rank, players:t.players, finalVillain:t.finalVillain, accent:t.accent, sessions:clone(t.sessions), documentMode:t.campaignPdf?'pdf':'editor', campaignPdf:t.campaignPdf||'', editorText:t.summary, templateId:t.id, templateName:t.name },
    dice:[], challenge:{ action:'Ação sem título', tn:14, edge:0, trouble:0, source:'hero', actor:t.heroes[0]?.id||'', threatTier:'minion', threatChoice:'minion-melee', ability:'Agility', extra:0 },
    scenario:{ preset:'empty', environment:'lab', width:20, height:14, baseTerrain:'floor', selectedTool:'select', selectedPiece:null, selectedMode:'run', zoom:1, obstacles:{}, terrain:{}, decor:{}, turnMovement:{}, movementSpent:{}, pieces:buildScenarioPieces(t.heroes) },
    initiative:[], playerNotes:Object.fromEntries(t.heroes.map(h=>[h.id,''])), notesMaster:''
  };
}
export function blankSeed(name='Nova Campanha'){
  return {
    heroes:[], villains:[], campaign:{},
    campaignContent:{ title:name, subtitle:'Campanha personalizada', summary:'', rank:4, players:0, finalVillain:'', accent:'#ef3340', sessions:[], documentMode:'editor', campaignPdf:'', editorText:'', templateId:'blank', templateName:'Em branco' },
    dice:[], challenge:{ action:'Ação sem título', tn:14, edge:0, trouble:0, source:'hero', actor:'', threatTier:'minion', threatChoice:'minion-melee', ability:'Agility', extra:0 },
    scenario:{ preset:'empty', environment:'lab', width:20, height:14, baseTerrain:'floor', selectedTool:'select', selectedPiece:null, selectedMode:'run', zoom:1, obstacles:{}, terrain:{}, decor:{}, turnMovement:{}, movementSpent:{}, pieces:[] },
    initiative:[], playerNotes:{}, notesMaster:''
  };
}
